import { Icon } from '@cetus/ui-kit'
import { d, fixD } from '@cetus/utils'
import {
  Box,
  Button,
  Center,
  Flex,
  Input,
  InputGroup,
  InputGroupProps,
  InputRightElement,
  Modal,
  ModalBody,
  ModalCloseButton,
  ModalContent,
  ModalHeader,
  ModalOverlay,
  Text,
  VStack
} from '@chakra-ui/react'
import { useEffect, useState } from 'react'

interface SlippageSettingProps {
  isOpen: boolean
  onClose: () => void
  value: number
  onChange: (slippage: number) => void
  compact?: boolean
}

export default function SlippageSetting(props: SlippageSettingProps) {
  const { isOpen, onClose, value, onChange, compact = false } = props
  const defaultFeeList = ['0.1', '0.5', '1']
  const [inputValue, setInputValue] = useState('')
  const [isCapture, setIsCapture] = useState(false)

  const handleChange = (event: any) => {
    const input = event.target.value
    const str = input.replace(/[^\d^.]+/g, '')
    const res = str && str[str.length - 1] != '.' && str.length > 3 && str?.includes('.') ? fixD(str, 2) : str
    setInputValue(res)
  }

  const selectValue = (value: string) => {
    setInputValue(value)
  }

  useEffect(() => {
    if (value) {
      setInputValue(String(value))
    }
  }, [value])

  useEffect(() => {
    if (value) {
      setInputValue(String(value))
    }
  }, [isOpen])

  const handleConfirm = () => {
    if (inputValue) {
      const s = d(inputValue).toNumber()
      onChange(s)
    }
    onClose()
  }

  return (
    <Modal isOpen={isOpen} onClose={onClose} isCentered>
      <ModalOverlay />
      <ModalContent>
        <ModalHeader fontWeight="500">Settings</ModalHeader>
        <ModalCloseButton />
        <ModalBody pb="16px">
          <Box>
            <Flex align="center">
              <Icon xlinkHref="#icon-icon_verticalslider" />
              <Text ml="8px">Slippage Tolerance</Text>
            </Flex>
            <Box
              bg={compact ? (Number(inputValue) > 50 ? 'primary_red_opacity.10' : 'primary_yellow_opacity.10') : 'transparent'}
              borderRadius="12px"
            >
              <VStack gap="20px" mt="8px">
                <Flex
                  w="100%"
                  justifyContent="center"
                  alignItems="center"
                  borderRadius="12px"
                  border="1px solid"
                  borderColor="border"
                  background="bg_secondary"
                  h="48px"
                >
                  {defaultFeeList.map(item => {
                    return (
                      <Center
                        flex="1"
                        bg={item === String(inputValue) ? '#1A1C25 !important' : 'transparent'}
                        key={item}
                        cursor="pointer"
                        h="calc(100% - 6px)"
                        margin="3px"
                        borderRadius="8px"
                        onClick={() => selectValue(item)}
                      >
                        <Text color={item === String(inputValue) ? 'text_highlight' : 'text_paragraph'}>{item}%</Text>
                      </Center>
                    )
                  })}
                  {compact && (
                    <CustomInput
                      compact
                      inputValue={inputValue}
                      handleChange={handleChange}
                      wrapStyle={{
                        flex: '0 0 150px',
                        mr: '-1px',
                        borderRadius: '0 12px 12px 0'
                      }}
                    />
                  )}
                </Flex>
                {!compact && <CustomInput inputValue={inputValue} handleChange={handleChange} />}
              </VStack>
              {inputValue && (Number(inputValue) > 1 || Number(inputValue) < 0.05) ? (
                <Flex w="100%">
                  {Number(inputValue) < 0.05 ? (
                    <Flex
                      w="100%"
                      justifyContent="center"
                      pt="28px"
                      mt="-20px"
                      pb="8px"
                      borderRadius="12px"
                      bg={compact ? 'transparent' : 'primary_yellow_opacity.10'}
                    >
                      <Text fontSize="xs" color="primary_yellow" ml="4px">
                        Slippage is low. Your transaction may fail.
                      </Text>
                    </Flex>
                  ) : null}
                  {Number(inputValue) <= 50 && Number(inputValue) > 1 ? (
                    <Flex
                      w="100%"
                      justifyContent="center"
                      pt="28px"
                      mt="-20px"
                      pb="8px"
                      borderRadius="12px"
                      bg={compact ? 'transparent' : 'primary_yellow_opacity.10'}
                    >
                      <Text fontSize="xs" color="primary_yellow" ml="4px">
                        Your transaction may be frontrun.
                      </Text>
                    </Flex>
                  ) : null}
                  {Number(inputValue) > 50 ? (
                    <Flex
                      w="100%"
                      justifyContent="center"
                      pt="28px"
                      mt="-20px"
                      pb="8px"
                      borderRadius="12px"
                      bg={compact ? 'transparent' : 'primary_red_opacity.10'}
                    >
                      <Text fontSize="xs" color="primary_red" ml="4px">
                        Enter a valid slippage percentage
                      </Text>
                    </Flex>
                  ) : null}
                </Flex>
              ) : null}
            </Box>
          </Box>

          <Flex align="center" justifyContent="space-between" mt="20px" gap="16px">
            <Button flex="1" h="42px" variant="ghost" onClick={onClose}>
              Cancel
            </Button>
            <Button flex="1" h="42px" onClick={handleConfirm} isDisabled={Number(inputValue) > 50 || Number(inputValue) < 0.01}>
              Confirm
            </Button>
          </Flex>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}

interface CustomInputProps {
  inputValue: string
  handleChange: (event: any) => void
  wrapStyle?: InputGroupProps
  compact?: boolean
}

const CustomInput = ({ inputValue, handleChange, wrapStyle = {}, compact = false }: CustomInputProps) => {
  return (
    <InputGroup
      alignItems="center"
      justifyContent="center"
      w="100%"
      background="bg_secondary"
      borderRadius="12px"
      border="1px solid"
      borderColor="border"
      h="48px"
      p="13px 16px"
      position="relative"
      {...wrapStyle}
    >
      <Text pr="8px" h="20px" lineHeight="20px" borderRight="1px solid" borderColor={compact ? 'transparent' : 'border'}>
        Custom
      </Text>
      <Input
        borderRadius="8px"
        type="number"
        h="40px"
        mr="2px"
        border="none"
        variant="outline"
        value={inputValue}
        onChange={handleChange}
        textAlign="right"
        fontSize="sm"
        placeholder="0.0"
        pr={{
          base: '14px',
          lg: '8px'
        }}
        pl={{
          base: '12px',
          lg: '16px'
        }}
      />
      <InputRightElement
        width="20px"
        height="40px"
        top="3px"
        right={{
          base: '12px',
          lg: '8px'
        }}
      >
        <Text fontSize="sm" color="text_caption">
          %
        </Text>
      </InputRightElement>
    </InputGroup>
  )
}
